css:
.tg { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); gap: 1px; background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.08); border-radius: 14px; overflow: hidden; }
.tg-i { background: #041a2c; padding: 28px; display: flex; flex-direction: column; gap: 10px; }
.tg-v { font-family: var(--font-heading); font-weight: 700; font-size: 48px; line-height: 1; color: #f4fbff; }
.tg-i:first-child .tg-v { color: #00fbff; }
.tg-d { font-size: 15px; line-height: 1.55; color: #c4d4e2; }
